import {escapeHTML as e,uid} from './store.js';

const W=216,H=86;
export function connectionCurve(a,b){
  const right=b.x>=a.x,start={x:a.x+(right?W:0),y:a.y+H/2},end={x:b.x+(right?0:W),y:b.y+H/2};
  const bend=Math.max(75,Math.abs(end.x-start.x)*.5),sign=right?1:-1;
  const lift=Math.abs(b.x-a.x)>450&&Math.abs(b.y-a.y)<H?-150:0;
  return {path:`M ${start.x} ${start.y} C ${start.x+sign*bend} ${start.y+lift}, ${end.x-sign*bend} ${end.y+lift}, ${end.x} ${end.y}`,x:(start.x+end.x)/2,y:(start.y+end.y)/2+lift*.75};
}
export function mountConnections(main,n,targets,{save,heading,notify,openDocument,documents,confirmDelete}){
  const abort=new AbortController(),opts={signal:abort.signal};
  const known=new Map(targets.map(t=>[t.id,t]));
  if(!Array.isArray(n.connectionBoard))n.connectionBoard=[...new Set(n.relations.flatMap(r=>[r.from,r.to]))];
  n.connectionBoard=n.connectionBoard.filter(id=>known.has(id));
  if(!n.connectionPositions||typeof n.connectionPositions!=='object')n.connectionPositions={};
  let selected='',relation='',connecting='',drag=null,scale=1,offset={x:0,y:0},raf=0,query='';
  const icons={Personagem:'♙',Documento:'▤',Criatura:'♧',Lugar:'⌖',Trama:'⌘'};
  const point=id=>n.connectionPositions[id];
  const columns=()=>Math.max(1,Math.min(3,Math.floor(((main.querySelector('#connectionViewport')?.clientWidth||Math.max(320,main.clientWidth-330))-40)/300)));
  const freshPoint=()=>{const cols=columns();for(let i=0;i<500;i++){const p={x:70+i%cols*340,y:90+Math.floor(i/cols)*190};if(!n.connectionBoard.some(id=>point(id)&&Math.abs(point(id).x-p.x)<W+30&&Math.abs(point(id).y-p.y)<H+30))return p;}return {x:70,y:90};};
  for(const id of n.connectionBoard){const p=point(id);if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y))n.connectionPositions[id]=freshPoint();}
  main.innerHTML=`<div class="page connections-page">${heading('LIGAÇÕES QUE CONTAM HISTÓRIAS','Conexões','Arraste o ponto de um cartão até outro para conectar.')}<div class="connection-workspace"><aside class="connection-library"><div class="connection-library-head"><strong>Itens do seu mundo</strong><small>Adicione ao quadro para conectar</small><input id="connectionSearch" type="search" aria-label="Buscar itens para conectar" placeholder="Buscar personagem, lugar…"></div><div id="connectionLibrary"></div></aside><section class="connection-board-area" aria-label="Quadro de conexões"><div class="connection-board-toolbar"><span id="connectionHint" role="status"></span><div class="connection-view-tools"><button class="icon-button" id="connectionZoomOut" aria-label="Diminuir quadro">−</button><span id="connectionZoomValue">100%</span><button class="icon-button" id="connectionZoomIn" aria-label="Ampliar quadro">＋</button><button class="button ghost" id="connectionFit">Enquadrar</button><button class="button ghost" id="connectionArrange">Organizar</button></div></div><div id="connectionViewport" class="connection-viewport" tabindex="0" aria-label="Quadro: arraste o fundo para navegar"><div id="connectionSurface" class="connection-surface"><svg class="connection-lines" width="8000" height="8000" aria-label="Linhas das conexões"><defs><marker id="connectionArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs><g id="connectionEdges"></g><path id="connectionDraft" class="connection-draft" hidden/></svg><div id="connectionCards"></div></div><div id="connectionEmpty" class="connection-empty"><span>◇</span><h2>Comece com duas ideias.</h2><p>Adicione dois itens da lista ao quadro.<br>Depois, arraste de um ponto ao outro.</p></div></div><div class="connection-footer"><span>◉ Arraste o ponto para conectar</span><span>⤧ Arraste o cartão para mover · o fundo para navegar</span><button id="connectionCancel" class="text-link" hidden>Cancelar conexão · Esc</button></div></section></div><section id="connectionInspector" class="connection-inspector" aria-label="Detalhes da seleção"></section></div>`;
  const $=s=>main.querySelector(s),viewport=$('#connectionViewport'),surface=$('#connectionSurface');
  const listen=(el,type,fn)=>el.addEventListener(type,fn,opts);
  function library(){const list=targets.filter(t=>(t.name+' '+t.kind).toLocaleLowerCase('pt-BR').includes(query));$('#connectionLibrary').innerHTML=list.map(t=>`<button class="connection-library-item" data-add="${e(t.id)}" aria-label="${n.connectionBoard.includes(t.id)?'Localizar':'Adicionar'} ${e(t.name)}"><span class="connection-type-icon">${icons[t.kind]||'◇'}</span><span><strong>${e(t.name)}</strong><small>${e(t.kind)}</small></span><span class="connection-add-symbol">${n.connectionBoard.includes(t.id)?'↗':'＋'}</span></button>`).join('')||'<p class="help">Nenhum item encontrado.</p>';}
  function hint(){const source=known.get(connecting);$('#connectionHint').textContent=source?`${source.name} → escolha o destino`:'Seu quadro de relações';$('#connectionCancel').hidden=!connecting;viewport.classList.toggle('is-connecting',!!connecting);}
  function transform(){surface.style.transform=`translate(${offset.x}px,${offset.y}px) scale(${scale})`;$('#connectionZoomValue').textContent=Math.round(scale*100)+'%';}
  function cards(){const related=new Set(n.relations.filter(r=>r.from===selected||r.to===selected).flatMap(r=>[r.from,r.to]));$('#connectionCards').innerHTML=n.connectionBoard.map(id=>{const t=known.get(id),p=point(id);return `<article class="connection-node ${selected===id?'selected':''} ${connecting===id?'source':''} ${selected&&selected!==id&&!related.has(id)?'unrelated':''}" data-node="${e(id)}" style="left:${p.x}px;top:${p.y}px"><button class="connection-node-body" data-select="${e(id)}" aria-label="Selecionar ${e(t.name)}"><span class="connection-type-icon">${icons[t.kind]||'◇'}</span><span><small>${e(t.kind)}</small><strong>${e(t.name)}</strong></span></button><button class="connection-port" data-port="${e(id)}" aria-label="Conectar ${e(t.name)}" title="Arraste até outro cartão ou clique e escolha o destino"><span>＋</span></button></article>`;}).join('');$('#connectionEmpty').hidden=!!n.connectionBoard.length;edges();hint();}
  function edges(){const live=n.relations.filter(r=>n.connectionBoard.includes(r.from)&&n.connectionBoard.includes(r.to));const groups=new Map();for(const r of live){const key=[r.from,r.to].sort().join(':');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}$('#connectionEdges').innerHTML=live.map(r=>{const curve=connectionCurve(point(r.from),point(r.to)),group=groups.get([r.from,r.to].sort().join(':')),index=group.indexOf(r),shift=(index-(group.length-1)/2)*46;const y=curve.y+shift;const active=relation===r.id||selected&&(r.from===selected||r.to===selected);return `<g class="connection-edge ${active?'active':''} ${selected&&!active?'unrelated':''}"><path class="connection-edge-hit" d="${curve.path}" data-edge="${e(r.id)}"/><path class="connection-edge-line" d="${curve.path}" marker-end="url(#connectionArrow)"/><foreignObject x="${curve.x-96}" y="${y-15}" width="192" height="34"><button xmlns="http://www.w3.org/1999/xhtml" class="connection-edge-label" data-edge="${e(r.id)}" title="${e(known.get(r.from).name)} → ${e(r.label)} → ${e(known.get(r.to).name)}">${e(r.label)} <span>→</span></button></foreignObject></g>`;}).join('');}
  function inspector(){const r=n.relations.find(r=>r.id===relation),t=known.get(selected);if(r){$('#connectionInspector').innerHTML=`<div class="connection-inspector-title"><span class="eyebrow">RELAÇÃO SELECIONADA</span><h2>${e(known.get(r.from)?.name||'Item removido')} <span>→</span> ${e(known.get(r.to)?.name||'Item removido')}</h2></div><form id="connectionForm"><label class="field"><span>Como se conectam?</span><input name="label" value="${e(r.label)}" maxlength="80" placeholder="Ex.: é aliado de" required></label><label class="field"><span>Anotações</span><textarea name="description" rows="2" maxlength="4000">${e(r.description||'')}</textarea></label><div class="toolbar"><button class="button" type="submit">Salvar relação</button><button class="button ghost" type="button" id="connectionReverse">⇄ Inverter direção</button><button class="text-link" type="button" id="connectionDelete">Excluir conexão</button></div></form>`;listen($('#connectionForm'),'submit',ev=>{ev.preventDefault();const fd=new FormData(ev.target);r.label=String(fd.get('label')).trim()||'Conectado a';r.description=String(fd.get('description'));save();edges();notify('Relação salva.');});listen($('#connectionReverse'),'click',()=>{[r.from,r.to]=[r.to,r.from];save();edges();inspector();});listen($('#connectionDelete'),'click',()=>confirmDelete('Excluir conexão?','Os itens do mundo serão preservados.',()=>{n.relations=n.relations.filter(item=>item.id!==r.id);}));return;}
    if(!t){$('#connectionInspector').innerHTML='<p class="help">Clique em um cartão para ver suas relações ou no nome de uma linha para editar.</p>';return;}
    const links=n.relations.filter(r=>r.from===t.id||r.to===t.id);$('#connectionInspector').innerHTML=`<div class="connection-inspector-title"><span class="eyebrow">${e(t.kind)}</span><h2>${e(t.name)}</h2><p>${e(t.description.slice(0,400))||'Ainda sem descrição.'}</p><div class="toolbar"><button class="button ghost" id="connectionStart">＋ Conectar a outro item</button>${documents.some(d=>d.id===t.id)?'<button class="button ghost" id="connectionOpen">Abrir documento ↗</button>':''}<button class="text-link" id="connectionHide">Retirar do quadro</button></div></div><div class="connection-list"><strong>${links.length} ${links.length===1?'relação':'relações'}</strong>${links.map(r=>`<button data-inspect-edge="${e(r.id)}"><span>${e(known.get(r.from)?.name||'Item removido')}</span><small>${e(r.label)} →</small><span>${e(known.get(r.to)?.name||'Item removido')}</span></button>`).join('')||'<p class="help">Arraste o ponto deste cartão até outro para criar uma relação.</p>'}</div>`;listen($('#connectionStart'),'click',()=>{connecting=t.id;cards();});if($('#connectionOpen'))listen($('#connectionOpen'),'click',()=>openDocument(t.id));listen($('#connectionHide'),'click',()=>{n.connectionBoard=n.connectionBoard.filter(id=>id!==t.id);selected='';save();library();cards();inspector();});}
  function selectNode(id){if(connecting&&connecting!==id){connect(connecting,id);return;}selected=id;relation='';cards();inspector();}
  function connect(from,to){if(from===to)return;const existing=n.relations.find(r=>r.from===from&&r.to===to);if(existing){relation=existing.id;notify('Esses itens já têm uma conexão nesta direção.');}else{const r={id:uid(),from,to,label:'Conectado a',description:''};n.relations.push(r);relation=r.id;save();notify('Conexão criada. Você pode dar um nome à relação abaixo.');}connecting='';selected='';cards();inspector();$('#connectionForm input')?.focus({preventScroll:true});}
  function fit(){if(!n.connectionBoard.length)return;const pts=n.connectionBoard.map(point),minX=Math.min(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxX=Math.max(...pts.map(p=>p.x+W)),maxY=Math.max(...pts.map(p=>p.y+H));scale=Math.max(.2,Math.min(1.1,(viewport.clientWidth-100)/(maxX-minX),(viewport.clientHeight-100)/(maxY-minY)));offset={x:(viewport.clientWidth-(maxX-minX)*scale)/2-minX*scale,y:(viewport.clientHeight-(maxY-minY)*scale)/2-minY*scale};transform();}
  function zoom(factor){const next=Math.max(.2,Math.min(1.6,scale*factor)),cx=viewport.clientWidth/2,cy=viewport.clientHeight/2;offset={x:cx-(cx-offset.x)*next/scale,y:cy-(cy-offset.y)*next/scale};scale=next;transform();}
  function local(ev){const r=viewport.getBoundingClientRect();return {x:(ev.clientX-r.left-offset.x)/scale,y:(ev.clientY-r.top-offset.y)/scale};}
  function drawDraft(ev){const p=point(drag?.id||connecting),to=local(ev),x=p.x+W,y=p.y+H/2;const draft=$('#connectionDraft');draft.hidden=false;draft.setAttribute('d',`M ${x} ${y} C ${x+90} ${y}, ${to.x-90} ${to.y}, ${to.x} ${to.y}`);const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-node]');main.querySelectorAll('.connection-drop-target').forEach(el=>el.classList.remove('connection-drop-target'));if(hit&&hit.dataset.node!==(drag?.id||connecting))hit.classList.add('connection-drop-target');}
  listen(main,'click',ev=>{const add=ev.target.closest('[data-add]');if(add){const id=add.dataset.add;if(!n.connectionBoard.includes(id)){n.connectionPositions[id]=freshPoint();n.connectionBoard.push(id);save();library();cards();}selectNode(id);fit();return;}const edge=ev.target.closest('[data-edge],[data-inspect-edge]');if(edge){relation=edge.dataset.edge||edge.dataset.inspectEdge;selected='';connecting='';cards();inspector();return;}const port=ev.target.closest('[data-port]');if(port){if(drag?.moved)return;const id=port.dataset.port;if(connecting&&connecting!==id)connect(connecting,id);else{connecting=connecting===id?'':id;cards();}return;}const node=ev.target.closest('[data-select]');if(node)selectNode(node.dataset.select);});
  listen(viewport,'pointerdown',ev=>{if(ev.button!==0||ev.target.closest('[data-edge]'))return;const port=ev.target.closest('[data-port]'),node=ev.target.closest('[data-node]');if(connecting&&node&&node.dataset.node!==connecting){connect(connecting,node.dataset.node);ev.preventDefault();return;}drag={type:port?'connect':node?'move':'pan',id:port?.dataset.port||node?.dataset.node,startX:ev.clientX,startY:ev.clientY,origin:node?{...point(node.dataset.node)}:{...offset},moved:false,pointer:ev.pointerId};viewport.setPointerCapture(ev.pointerId);if(port){connecting=port.dataset.port;hint();}ev.preventDefault();});
  listen(viewport,'pointermove',ev=>{if(!drag)return;const dx=ev.clientX-drag.startX,dy=ev.clientY-drag.startY;if(Math.hypot(dx,dy)>4)drag.moved=true;if(!drag.moved)return;if(drag.type==='connect'){drawDraft(ev);return;}if(drag.type==='pan'){offset={x:drag.origin.x+dx,y:drag.origin.y+dy};transform();return;}const p={x:Math.max(20,Math.min(7400,drag.origin.x+dx/scale)),y:Math.max(20,Math.min(7400,drag.origin.y+dy/scale))};n.connectionPositions[drag.id]=p;const node=[...main.querySelectorAll('[data-node]')].find(el=>el.dataset.node===drag.id);node.style.left=p.x+'px';node.style.top=p.y+'px';if(!raf)raf=requestAnimationFrame(()=>{raf=0;edges();});});
  function stop(ev,cancel=false){if(!drag)return;const d=drag;drag=null;if(viewport.hasPointerCapture(d.pointer))viewport.releasePointerCapture(d.pointer);$('#connectionDraft').hidden=true;main.querySelectorAll('.connection-drop-target').forEach(el=>el.classList.remove('connection-drop-target'));if(cancel){connecting='';hint();return;}if(d.type==='connect'&&d.moved){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-node]');if(target&&target.dataset.node!==d.id)connect(d.id,target.dataset.node);else{connecting='';hint();}return;}if(d.type==='move'&&d.moved){save();edges();return;}if(d.type==='move')selectNode(d.id);if(d.type==='pan'&&!d.moved){connecting='';selected='';relation='';cards();inspector();}}
  listen(viewport,'pointerup',ev=>stop(ev));listen(viewport,'pointercancel',ev=>stop(ev,true));
  // Pointer capture makes click targets inconsistent across browsers; handle the tap here.
  listen(viewport,'click',ev=>{if(ev.detail>0&&ev.target.closest('[data-select],[data-port]'))ev.stopPropagation();});
  listen(viewport,'pointerup',ev=>{const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-port]');if(hit&&!drag&&connecting===hit.dataset.port)hint();});
  listen($('#connectionSearch'),'input',ev=>{query=ev.target.value.toLocaleLowerCase('pt-BR');library();});
  listen($('#connectionZoomOut'),'click',()=>zoom(1/1.2));listen($('#connectionZoomIn'),'click',()=>zoom(1.2));listen($('#connectionFit'),'click',fit);
  listen($('#connectionArrange'),'click',()=>{const cols=columns();n.connectionBoard.forEach((id,i)=>n.connectionPositions[id]={x:70+i%cols*340,y:90+Math.floor(i/cols)*190});save();cards();fit();});
  const cancel=()=>{connecting='';drag=null;$('#connectionDraft').hidden=true;cards();};listen($('#connectionCancel'),'click',cancel);listen(document,'keydown',ev=>{if(ev.key==='Escape'&&connecting)cancel();});
  const resize=new ResizeObserver(()=>fit());resize.observe(viewport);
  library();cards();inspector();fit();
  return ()=>{abort.abort();resize.disconnect();cancelAnimationFrame(raf);};
}
